"""卷六合作全文阅读后的草稿组装；仅写本卷，不作正式入库。"""
import json,pathlib,re,collections
B=pathlib.Path(__file__).resolve().parent
S=json.loads((B.parent/'source.json').read_text(encoding='utf-8'))
SID=S['source_id']; REV=S['revision']
N=[json.loads(x) for x in (B/'chapter-notes.jsonl').read_text(encoding='utf-8').splitlines() if x.strip()]
N.sort(key=lambda x:x['chapter_id'])
V=next(v for v in S['volumes'] if v['volume']==6)
IDS=[s['chapter_id'] for u in V['units'] for s in u['segments']]
assert len(N)==244 and [n['chapter_id'] for n in N]==IDS
BY=collections.defaultdict(list)
for n in N:BY[int(re.search(r'第(\d+)章',n['title']).group(1))].append(n)
def dump(name,x):(B/name).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def ev(*chs,kind='fact'):
 return [dict(source_id=SID,revision=REV,chapter_id=n['chapter_id'],start_line=n['start_line'],end_line=n['end_line'],claim_kind=kind) for c in chs for n in BY[c]]
def origin(t,k):return f'{SID}/full-20261025/vol06/{t}/{k}'

ATTR={'primary':{'count':44,'chapter_ids':IDS[:44],'method':'主代理实际逐章全文阅读，现任代理复用原逐章记录进行整合，未声称个人重读'},'/root/zongheng_vol05_full':{'count':200,'chapter_ids':IDS[44:],'method':'接续后实际逐章全文读取、核对BEGIN/END，每2—4单元写笔记和状态'}}
dump('read-log.json',dict(source_id=SID,revision=REV,volume=6,review_status='draft',complete_book=False,complete_volume_read=True,
 scope='卷六《月神殿祭》；原章题531—772，242个不同原章号，244个正文阅读单元/原索引片段；689和690各分（一）（二），不按raw减一机械换算',
 reader='collaborative',reader_attribution=ATTR,method='按1—2原索引片段输出带行号全文，逐批核对END；每2—4单元持久化基于真实阅读的笔记及状态。全部正文读完，无待补截断；整合只使用本卷已读事实及明确注明的桥接背景。',
 chapter_count=244,distinct_original_chapter_numbers=242,first_line=N[0]['start_line'],last_line=N[-1]['end_line'],
 chapters=[dict(chapter_id=n['chapter_id'],title=n['title'],start_line=n['start_line'],end_line=n['end_line'],full_text_read=True,reader=n['reader'],index_number=int(n['chapter_id'].split('-')[1]),original_chapter_number=int(re.search(r'第(\d+)章',n['title']).group(1))) for n in N],
 reading_units=[dict(unit_number=i+1,chapter_ids=[s['chapter_id'] for s in u['segments']]) for i,u in enumerate(V['units'])],truncated_pending=[],
 anomalies=['原689与690各分两完整章题单元，全部保留，未擅合正文或人物。','组装草稿时有多文件非正文输出截断，所需父代理笔记已拆分补阅，不属于未读正文。','主代理前44单元与本代理后200单元分开署名；不得表述为现任代理独自重读全卷。'],
 quality_boundary='证据与图引用校验只能证明定位、覆盖和结构合法，不代表文学解释或用户审美已确认。'))

D={k:[] for k in ['worldbuilding','characters','plot','style','narrative','dialogue','pacing','themes','continuity']}
def obs(dim,key,fact,inf,chs,q):
 D[dim].append(dict(id='v06-'+dim+'-'+key,fact=dict(text=fact,claim_kind='fact',evidence=ev(*chs)),inference=dict(text=inf,claim_kind='inference',evidence=ev(*chs,kind='inference')),transfer_question=q,review_status='draft'))

obs('worldbuilding','conditional-power','五转加属性与领域，火龙初获说明可骑60分钟/冷却24小时，后段时长叙述另存异常；后有狭路不可进龙、技能已生效不可被普通控制撤销、Boss魔免等限制。','强力不是一个固定等级评价，而是空间、执行、持续时间和规则优先级的组合；每次换条件能重新制造难题。',[535,538,551,558,574,769],'新能力有哪一条可观测边界，敌方怎样利用它？')
obs('worldbuilding','resource-chain','阿瓦隆50图碎接任务，命运套200/50万荣誉且死亡包内全掉；神殿圣灵惩戒原将持续至第十死，但冰兰当章清除，未实际掉十级；赤霄需圣域50/声望320万。','资源取得、解锁、使用、损失和再恢复被拆成多层，获奖不能自动抹掉后续发展空间。',[541,545,561,649,766,767],'获得稀缺物后还会被哪一种不同成本约束？')
