def card(t,k,title,content,chs):
 x=dict(asset_type=t,scope='reusable-pattern' if t=='pattern' else 'source-analysis',title=title,origin_key=origin(t,k),tags=['作者:失落叶','作品:网游之纵横天下','卷六:月神殿祭','待审阅'],content=content,evidence=ev(*chs,kind='synthesis' if t=='pattern' else 'fact'),user_notes='',favorite=False,review_status='draft')
 CARDS.append(x);return x
